import Foundation
import CoreData

let model = NSManagedObjectModel()
let entity = NSEntityDescription()
entity.name = "Note"
entity.managedObjectClassName = "NSManagedObject"
let textAttr = NSAttributeDescription()
textAttr.name = "text"
textAttr.attributeType = .stringAttributeType
textAttr.isOptional = false
entity.properties = [textAttr]
model.entities = [entity]

let coordinator = NSPersistentStoreCoordinator(managedObjectModel: model)
try coordinator.addPersistentStore(ofType: NSInMemoryStoreType, configurationName: nil, at: nil, options: nil)
let context = NSManagedObjectContext(concurrencyType: .mainQueueConcurrencyType)
context.persistentStoreCoordinator = coordinator

let n1 = NSManagedObject(entity: entity, insertInto: context)
n1.setValue("A", forKey: "text")
let n2 = NSManagedObject(entity: entity, insertInto: context)
n2.setValue("B", forKey: "text")
try context.save()

let request = NSFetchRequest<NSManagedObject>(entityName: "Note")
let count = try context.count(for: request)
print("Notes: \(count)")

